import{_ as a}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as t}from"./chunks/M-S-Search.C3B92iCp.js";import{_ as e}from"./chunks/CrystalBall.BdqnOTQQ.js";import{_ as o,o as s,c as r,a3 as n}from"./chunks/framework.g9mfNVRQ.js";const _=JSON.parse('{"title":"Impostazioni","description":"","frontmatter":{"source_hash":"4f30078921","source_commit":"7a18e7c","i18n_outdated":true},"headers":[],"relativePath":"it/use/settings.md","filePath":"it/use/settings.md"}'),p={name:"it/use/settings.md"};function l(d,i,c,m,u,h){return s(),r("div",null,[...i[0]||(i[0]=[n('<div class="admonition xdrip"><p class="admonition-title"><img src="'+a+'" style="zoom:75%;"></p><p> Impostazioni</p></div><p>Le impostazioni di xDrip sono moltissime: se non trovi quello che cerchi, usa la lente di ricerca in alto a destra e inserisci la parola chiave che ti interessa.</p><img src="'+t+'" style="zoom:75%;"><br><h3 id="glucose-units" tabindex="-1">Unità di Misura Glicemia <a class="header-anchor" href="#glucose-units" aria-label="Permalink to &quot;Unità di Misura Glicemia {#glucose-units}&quot;">​</a></h3><div class="admonition xdrip"><p class="admonition-title">Unità di Misura Glicemia</p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_ruler_grey600_48dp.png" style="width:5%;"> mmol/l o mg/dl alta e bassa</p></div><p>In questo menu puoi selezionare le unità usate da xDrip (mg/dl o mmol/l) e impostare gli obiettivi alto e basso.</p><div class="admonition xdripitem"><p class="admonition-title">Unità di Misura Glicemia</p><p> mg/dl o mmol/l</p></div><p>Questi due obiettivi stabiliscono quando i punti della glicemia sul grafico cambiano colore sopra o sotto l&#39;obiettivo.</p><div class="admonition xdripitem"><p class="admonition-title">Valore Massimo</p><p> 170</p></div><div class="admonition xdripitem"><p class="admonition-title">Valore Minimo</p><p> 70</p></div><h3 id="alarms-and-alerts" tabindex="-1"><a href="./alarms.html">Allarmi e Avvisi</a> <a class="header-anchor" href="#alarms-and-alerts" aria-label="Permalink to &quot;[Allarmi e Avvisi](./alarms) {#alarms-and-alerts}&quot;">​</a></h3><div class="admonition xdrip"><p class="admonition-title">Allarmi e Avvisi</p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_add_alert_grey600_48dp.png" style="width:5%;"> Glicemia, Calibrazioni e altri avvisi</p></div><h3 id="hardware-data-source" tabindex="-1"><a href="./../install/datasource.html">Dati Hardware di origine</a> <a class="header-anchor" href="#hardware-data-source" aria-label="Permalink to &quot;[Dati Hardware di origine](../install/datasource) {#hardware-data-source}&quot;">​</a></h3><p>Queste impostazioni dipendono dalla sorgente dati selezionata.</p><div class="admonition xdrip"><p class="admonition-title">Dati Hardware di origine</p></div><h3 id="nfc-scan-features" tabindex="-1"><a href="./NFC.html">Funzionalità Scansione NFC</a> <a class="header-anchor" href="#nfc-scan-features" aria-label="Permalink to &quot;[Funzionalità Scansione NFC](./NFC) {#nfc-scan-features}&quot;">​</a></h3><p>Questo menu è visibile solo se scegli una sorgente dati Libre Bluetooth in Dati Hardware di origine. Se devi accedervi per modificare i parametri di smoothing dei sensori Libre, cambia temporaneamente la sorgente dati.</p><div class="admonition xdrip"><p class="admonition-title">Funzionalità Scansione NFC</p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_nfc_grey600_48dp.png" style="width:5%;"> Opzioni per scansionare sensori NFC con il telefono</p></div><h3 id="auto-configure" tabindex="-1"><a href="./copysettings.html#auto-configure">Configurazione automatica</a> <a class="header-anchor" href="#auto-configure" aria-label="Permalink to &quot;[Configurazione automatica](./copysettings#auto-configure) {#auto-configure}&quot;">​</a></h3><p>Configurazione automatica ti aiuta a copiare le impostazioni tra due app xDrip installate su telefoni diversi. Questa funzione e <a href="./copysettings.html#show-settings-qr-code">Mostra impostazioni dei codici QR</a> si trovano entrambe nella schermata &quot;Impostazioni di copia&quot;.</p><div class="admonition xdrip"><p class="admonition-title">Configurazione automatica</p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_qrscan.png" style="width:5%;"> Configurazione automatica utilizzando un codice QR.</p></div><h3 id="cloud-upload" tabindex="-1"><a href="./cloud.html">Caricamento nel Cloud</a> <a class="header-anchor" href="#cloud-upload" aria-label="Permalink to &quot;[Caricamento nel Cloud](./cloud) {#cloud-upload}&quot;">​</a></h3><p>Caricamento nel Cloud serve a configurare varie funzioni di condivisione e caricamento dei dati.</p><div class="admonition xdrip"><p class="admonition-title">Caricamento nel Cloud</p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_cloud_upload_grey600_48dp.png" style="width:5%;"> Opzioni per caricamento su Nightscout, MongoDB o Dexcom Share</p></div><h3 id="glucose-meters" tabindex="-1"><a href="./glucometer.html">Glucometri</a> <a class="header-anchor" href="#glucose-meters" aria-label="Permalink to &quot;[Glucometri](./glucometer) {#glucose-meters}&quot;">​</a></h3><p>Puoi collegare a xDrip dei glucometri compatibili.</p><div class="admonition xdrip"><p class="admonition-title">Glucometri</p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_touch_app_grey600_48dp.png" style="width:5%;"> Opzioni per glucometri wireless</p></div><h3 id="smart-watch-features" tabindex="-1"><a href="./../smartwatch/smartwatch.html">Caratteristiche Collegamenti Smart Watch</a> <a class="header-anchor" href="#smart-watch-features" aria-label="Permalink to &quot;[Caratteristiche Collegamenti Smart Watch](../smartwatch/smartwatch) {#smart-watch-features}&quot;">​</a></h3><p>Diversi smartwatch possono ricevere i dati da xDrip e mostrarli, alcuni possono persino funzionare come collector autonomo.</p><div class="admonition xdrip"><p class="admonition-title">Caratteristiche Collegamenti Smart Watch</p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_watch_grey600_48dp.png" style="width:5%;"> Opzioni per Smartwatch</p></div><h3 id="speak-readings" tabindex="-1"><a href="./speak.html">Letture Vocali</a> <a class="header-anchor" href="#speak-readings" aria-label="Permalink to &quot;[Letture Vocali](./speak) {#speak-readings}&quot;">​</a></h3><p>xDrip può usare il telefono per leggere ad alta voce valori e avvisi.</p><div class="admonition xdrip"><p class="admonition-title">Letture Vocali</p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_speak_reading_grey600_48dp.png" style="width:5%;"> Se il telefono è dotato di lettura vocale, leggerà ogni nuova lettura</p></div><h3 id="inter-app-settings" tabindex="-1"><a href="./interapp.html">Impostazioni Inter-app</a> <a class="header-anchor" href="#inter-app-settings" aria-label="Permalink to &quot;[Impostazioni Inter-app](./interapp) {#inter-app-settings}&quot;">​</a></h3><p>xDrip può ricevere dati da altre app o inviarne, e funzionare come web server locale.</p><div class="admonition xdrip"><p class="admonition-title">Impostazioni Inter-app</p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_open_in_app_grey600_48dp.png" style="width:5%;"> Per interagire con altre applicazioni compatibili</p></div><h3 id="less-common-settings" tabindex="-1"><a href="./lesscommon.html">Impostazioni Meno Usate</a> <a class="header-anchor" href="#less-common-settings" aria-label="Permalink to &quot;[Impostazioni Meno Usate](./lesscommon) {#less-common-settings}&quot;">​</a></h3><p>In questo menu sono disponibili altre impostazioni.</p><div class="admonition xdrip"><p class="admonition-title">Impostazioni Meno Usate</p><p> Debug e altre opzioni misc</p></div><h3 id="display" tabindex="-1"><a href="./display.html">xDrip+ impostazioni di visualizzazione</a> <a class="header-anchor" href="#display" aria-label="Permalink to &quot;[xDrip+ impostazioni di visualizzazione](./display) {#display}&quot;">​</a></h3><div class="admonition xdrip"><p class="admonition-title">xDrip+ impostazioni di visualizzazione</p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_chart_areaspline_grey600_48dp.png" style="width:5%;"> Personalizzazioni di visualizzazione</p></div><h3 id="predictive-simulations" tabindex="-1"><a href="./predictions.html">xDrip+ Impostazioni di simulazione predittiva</a> <a class="header-anchor" href="#predictive-simulations" aria-label="Permalink to &quot;[xDrip+ Impostazioni di simulazione predittiva](./predictions) {#predictive-simulations}&quot;">​</a></h3><div class="admonition xdrip"><p class="admonition-title">xDrip+ Impostazioni di simulazione predittiva</p><p> <img src="'+e+'" style="width:5%;"> L&#39;insulina, i rapporti Carb ecc per i modelli</p></div><h3 id="xdrip-sync" tabindex="-1"><a href="./sync.html">Impostazioni xDrip+ Sync</a> <a class="header-anchor" href="#xdrip-sync" aria-label="Permalink to &quot;[Impostazioni xDrip+ Sync](./sync) {#xdrip-sync}&quot;">​</a></h3><div class="admonition xdrip"><p class="admonition-title">Impostazioni xDrip+ Sync</p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_google_circles_communities_grey600_48dp.png" style="width:5%;"> Impostazioni per la sincronizzazione tra portatili</p></div><h3 id="motion-tracking" tabindex="-1"><a href="./motion.html">Rilevazione Movimento xDrip+</a> <a class="header-anchor" href="#motion-tracking" aria-label="Permalink to &quot;[Rilevazione Movimento xDrip+](./motion) {#motion-tracking}&quot;">​</a></h3><div class="admonition xdrip"><p class="admonition-title">Rilevazione Movimento xDrip+</p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_car_connected_grey600_48dp.png" style="width:5%;"> Rilevamento dei movimenti e modalità guida</p></div><h3 id="update-settings" tabindex="-1"><a href="./update.html">xDrip+ Impostazioni di aggiornamento</a> <a class="header-anchor" href="#update-settings" aria-label="Permalink to &quot;[xDrip+ Impostazioni di aggiornamento](./update) {#update-settings}&quot;">​</a></h3><div class="admonition xdrip"><p class="admonition-title">xDrip+ Impostazioni di aggiornamento</p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_briefcase_download_grey600_48dp.png" style="width:5%;"> Aggiornamenti automatici, rapporti di crash e Feedback per gli sviluppatori</p></div><h3 id="show-settings-qr-code" tabindex="-1"><a href="./copysettings.html#show-settings-qr-code">Mostra impostazioni dei codici QR</a> <a class="header-anchor" href="#show-settings-qr-code" aria-label="Permalink to &quot;[Mostra impostazioni dei codici QR](./copysettings#show-settings-qr-code) {#show-settings-qr-code}&quot;">​</a></h3><p>Questa funzione serve a trasferire le impostazioni tra telefoni.</p><div class="admonition xdrip"><p class="admonition-title">Mostra impostazioni dei codici QR</p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_qrcode_grey600_48dp.png" style="width:5%;"></p></div><h3 id="load-save-settings" tabindex="-1"><a href="./loadsavesettings.html">Carica / Salva impostazioni su memoria SD</a> <a class="header-anchor" href="#load-save-settings" aria-label="Permalink to &quot;[Carica / Salva impostazioni su memoria SD](./loadsavesettings) {#load-save-settings}&quot;">​</a></h3><p>Puoi fare un backup delle impostazioni di xDrip e recuperarle.</p><div class="admonition xdrip"><p class="admonition-title">Carica / Salva impostazioni su memoria SD</p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_content_save_grey600_48dp.png" style="width:5%;"></p></div><h3 id="insulin-pens" tabindex="-1"><a href="./pens.html">Penne Insuliniche</a> <a class="header-anchor" href="#insulin-pens" aria-label="Permalink to &quot;[Penne Insuliniche](./pens) {#insulin-pens}&quot;">​</a></h3><p>Alcune penne per insulina possono essere usate con xDrip.</p><div class="admonition xdrip"><p class="admonition-title">Penne Insuliniche</p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_mode_edit_grey_600_48dp.png" style="width:5%;"></p></div><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Ultima modifica 23/11/2026</em></a></p>',61)])])}const f=o(p,[["render",l]]);export{_ as __pageData,f as default};
